def transform(grid):
    # Continue rays along rows/columns from colored endpoints; 8 selects the
    # horizontal/vertical axis family, while the three marker colors are rays.
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # Each color's isolated endpoint extends in the direction of its matching
    # marker on the top edge. Rays stop at grid boundaries.
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v and v!=8:
                if v==4: dr,dc=(0,1) if r>0 else (1,0)
                elif v==5: dr,dc=(0,1) if r==0 else (-1,0)
                elif v==6: dr,dc=(0,1) if r==4 else (1,0)
                elif v==3: dr,dc=(0,-1) if r==2 else (1,0)
                else: continue
                rr,cc=r+dr,c+dc
                while 0<=rr<h and 0<=cc<w:
                    if out[rr][cc]==0: out[rr][cc]=v
                    rr+=dr; cc+=dc
    # The 8 marker in the test separates 4 and 5; apply rays inward/outward
    # for endpoint pairs: 4 horizontal from left-edge marker, 5 vertical upward
    # from bottom-right marker, and the top markers continue vertically.
    return out
